-- WoW Forever live realm (client 70888): Russian quest texts from twelve captures by a Russian player (2026-11-12, Teldrassil and
-- Darnassus) and one more (dump_1.60.1.70938_2026-11-13_07-45-40.pkt, Darkshore). Hand-in texts (quest_offer_reward_locale) and
-- progress texts (quest_request_items_locale), ruRU only, exactly as live sends them; line breaks become $B.
-- Most of our ruRU rows for these quests were copied from old captures with the capturing player's name typed into the text
-- ("Радиум", "Анудорини", "Айлерон", ...) and only the male word forms; live sends $n and $G male:female; forms. 79 hand-in and
-- 40 progress texts are new or replace ours; rows that already match live are left alone. Safe to run more than once.

ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = VALUES(`VerifiedBuild`);

ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = VALUES(`VerifiedBuild`);
-- The same five capture-player names are still typed into ruRU texts of quests these captures did not reach (456, 459, 486,
-- 927, 1581, 2499, 3361, 4495, 6063, 6102). None of them is an NPC name; put the player's own name back in their place.
UPDATE `quest_offer_reward_locale` SET `RewardText` = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`RewardText`,
  'Анудорини', '$n'), 'Радиум', '$n'), 'Айлерон', '$n'), 'Эльстан', '$n'), 'Миззрим', '$n')
  WHERE `locale` = 'ruRU' AND `RewardText` REGEXP 'Анудорини|Радиум|Айлерон|Эльстан|Миззрим';
UPDATE `quest_request_items_locale` SET `CompletionText` = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`CompletionText`,
  'Анудорини', '$n'), 'Радиум', '$n'), 'Айлерон', '$n'), 'Эльстан', '$n'), 'Миззрим', '$n')
  WHERE `locale` = 'ruRU' AND `CompletionText` REGEXP 'Анудорини|Радиум|Айлерон|Эльстан|Миззрим';
