INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(457, 'ruRU', 'Твои дела доказывают твою преданность природе, $n. Поверь, |3-6($c), несмотря на твою юность уже заметно, что тебя ждет блестящее будущее.', 70888),
(483, 'ruRU', 'Тебе удалось это сделать, $Gюный:юная:c; |3-6($c)! Славно! И как раз вовремя.', 70888),
(487, 'ruRU', 'Ты славно $Gпослужил:послужила; доброму народу Доланаара и Дарнасса, $Gотважный:отважная:c; |3-6($c). От имени всех Часовых Тельдрассила воздаю тебе хвалу.', 70888),
(488, 'ruRU', 'Ха-ха! Хорошая работенка!$b$bКто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать |3-6($r)? Я даже мечтать об этом не мог! Но раз уж так вышло... Наш милый мир полон неожиданностей.$b$bОбманули дурака на четыре кулака!', 70888),
(490, 'ruRU', 'Ты хорошо послужил:послужила; нам, $n, и получишь награду.', 70888),
(916, 'ruRU', 'Благодарю тебя, $n. Когда я вернусь в Дарнасс, я первым же делом сравню образцы яда из этих желез с ядами других пауков. Полагаю, что некоторые свойства яда связаны с ростом нового Древа Жизни.', 70888),
(917, 'ruRU', 'О, отлично. Я отправлю яйцо и яд в Дарнасс, а потом и сам вернусь туда, когда мои изыскания здесь будут завершены. Я многого ожидаю от этих образцов, $n. Твоя помощь оказалась поистине бесценной.', 70888),
(918, 'ruRU', 'Ты их $Gдобыл:добыла;. Славно!$B$BЯ посажу их в специально подготовленную почву. Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных. Может, позже ты еще увидишь результаты!', 70888),
(919, 'ruRU', 'Как много! Они распространяются с ужасающей скоростью. Надеюсь, мне удастся разгадать, что же за порча поразила их.$B$BБлагодарю за помощь, $n. Этот край благодаря твоим усилиям стал чище.', 70888),
(920, 'ruRU', 'А, $n. Я думал, что ты быстрее откликнешься на мой призыв. У меня есть важное задание, которое я хочу поручить тебе.', 70888),
(922, 'ruRU', 'А, росток древесника? Я хотел попытаться сам вырастить древесника, чтобы помочь Деналану в его изысканиях.$B$BК сожалению, я выяснил, что множество древесников поражено порчей, и ростки таких существ также наследуют ее от родителей. И не в моих силах это исправить.$B$BУ Деналана великий талант работать со всем, что растет. Если кто и найдет исцеление для будущих древесников, то это он. Возможно, он -  наша последняя надежда.', 70888),
(923, 'ruRU', 'Хорошая работа! Эти опухоли – симптом болезни древесников. Они наполнены ядом, от которого мы должны очистить наши новые земли.$B$BЯ уничтожу эти опухоли. Благодарю тебя, $n.', 70888),
(928, 'ruRU', 'А, понятно. Тебя послал Тенарон. Ну что ж, похоже, нам о многом нужно поговорить, многое сделать – но времени мало.$b$bДумаю, лучше не медлить и приступить к делу сейчас же.', 70888),
(929, 'ruRU', 'После битвы за гору Хиджал мы не знали, что делать дальше. Нордрассил дымился, опаленный огнем, и наше бессмертие – сама сущность нашего бытия! – было утрачено. $b$bИменно в эту пору испытаний Предатель вырвался из заточения и исчез Шан''до Ярость Бури. Настали темные времена.', 70888),
(930, 'ruRU', 'Ты $Gнашел:нашла; его на Тельдрассиле? Как интересно... Такой необычный плод. Может, семена занесло издалека? Может, даже из Азерота! И что-то в нем есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила.$B$BСпасибо тебе, $n. Теперь извини, мне нужно попристальнее его поизучать...', 70888),
(931, 'ruRU', 'Где ты это $Gнашел:нашла;? Я не видел таких растений с тех пор, как жил на Болоте Печали. А это было много десятилетий назад! Удивительно, как он попал в Тельдрассил. Да еще вырос до такой величины!$B$BСпасибо тебе, $n. Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком...', 70888),
(932, 'ruRU', 'Теперь, когда лорд Меленас упокоился навек, я могу заняться и другими делами. Прими мою благодарность, $n.', 70888),
(933, 'ruRU', 'Шан''до Ярость Бури так и не вернулся, и новостей про него до сих пор не поступало. Друиды были в смятении. После пропажи Малфуриона верховный друид Фэндрал Олений Шлем взял на себя руководство друидами, убедив Круг Древних на Темных Берегах, что нашему народу пора снова заполучить былую мощь и бессмертие.$b$bС одобрения Круга Олений Шлем и самые могучие друиды вырастили Тельдрассил, новое Древо Жизни.', 70888),
(935, 'ruRU', 'О, да, это та вода, о которой я просил. Тенарон и Коритрас улучили минутку передать ее... хотя гонца, может, и не самого надежного выбрали... хм-м.$b$bОднако теперь я могу вернуться к работе. Бремя бед Тельдрассила тяжким гнетом лежит на моих плечах. Но скоро я избавлюсь от этого ярма.$b$bВот, возьми. Может, тебе пригодится.', 70888),
(937, 'ruRU', 'Спасибо, ты мне очень $gпомог:помогла;. Давай я осмотрю эти пояса – посмотрим, укажут ли они на причину агрессии гарпий.', 70888),
(938, 'ruRU', 'О, благодарю тебя, $n! Я так боялась, что уж больше не увижу мою Туманну, скорбела всем сердцем о ее гибели, о том, что навек разлучилась с моей верной спутницей... Я в неоплатном долгу перед тобой! Прими мою вечную благодарность.', 70888),
(940, 'ruRU', 'Я-то думал, почему Древо-оракул так долго не связывается со мной... Сдается мне, что как только мы решаем одну проблему, немедленно возникает другая, еще более сложная.$b$bБоюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернем себе бессмертие. $b$bТем не менее, ты славно $Gсправился:справилась; с заданием Древа-оракула, и за усердие тебе положена награда.', 70888),
(947, 'ruRU', 'Большое вам спасибо, $n. Это отличные экземпляры!$B$BКстати, когда вы были у водопада Скалистый, заметили ли что-нибудь, что могло подтвердить опасения Дерев?$B$BДерева мудры, но я надеялся, что на сей раз они ошибаются.', 70888),
(953, 'ruRU', 'У нас очень немного записей, относящихся ко времени Войны Древних, а особенно – к периоду разрушения Источника Вечности. Что неудивительно, если вспомнить о том, какие ужасные события и катаклизмы тогда происходили.$B$BСпасибо вам, $N. С вашей помощью моя работа здесь окончена, и я смогу представить Кругу Древних полный доклад.', 70888),
(954, 'ruRU', 'Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, $gлюбезный:любезная:r; |3-6($r)? На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение...$B$BНо, прошу вас, пусть мой грубый язык не заставит вас уйти. Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания.', 70888),
(956, 'ruRU', 'Мне трудно поверить, что вещь, которую я сейчас держу в руках, так долго держала меня самого... Не будем тратить времени, $n. Когда печать будет уничтожена, я снова вольно смогу бродить по лесам.', 70888),
(963, 'ruRU', 'Благодарю тебя, $n. Может быть, было бы лучше... если бы я сам это сделал. Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную.$B$BПожалуйста, оставь меня наедине с моим горем...', 70888),
(966, 'ruRU', 'Большое спасибо, $n. Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников...$B$BХмм... Клан Темной Нити... Никогда раньше не слышал о такой группе. Пока у нас нет никаких сведений об их истории, практически невозможно сказать, в чем могут заключаться их планы.$B$BБольше нельзя тянуть. Нужно немедленно предупредить Делгрена.', 70888),
(982, 'ruRU', 'Ты $gоказал:оказала; нам огромную услугу. Мы проследим за тем, чтобы об этих вещах хорошо позаботились.$B$BЧто же касается тебя, прошу, прими это. Это самое малое, чем я могу отблагодарить тебя за смелость, проявленную ради восстановления справедливости.', 70888),
(983, 'ruRU', 'Когда вы кладете ножки крабов в приемник машины, то слышите, как шестерни начинают их перемалывать. По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли свое место. Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины.$B$B"Алло! Уфф... Алло! Ты ее $gпочинил:починила;! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить еще одну машинку?"', 70888),
(984, 'ruRU', 'Это и вправду ужасные новости, $n.$B$BПоскольку фурболги находятся так близко к Аубердину, нам придется приготовиться к неизбежному.$B$BСпасибо вам, $n.', 70888),
(985, 'ruRU', 'Смойте кровь с ваших доспехов, $n, и не мучайтесь из-за содеянного. Вместо этого вознесите благодарность судьбе. Вы уменьшили угрозу нашему народу здесь, в Аубердине, даже если весь Темный Берег пока еще находится в опасности из-за Мха Скверны.', 70888),
(997, 'ruRU', 'Наконец-то! Я уже давно жду эту редкую землю. Надеюсь, она еще свежая...$B$BСпасибо тебе за доставку, $n. Ты – |3-6($r), не $Gжалеющий:жалеющая; времени на благие дела!', 70888),
(1001, 'ruRU', 'Жужжалка оживает вскоре после того, как вы помещаете в нее глаза крепкозуба. После коротких помех вы слышите знакомый голосок.$B$B"Вино из крабов лучше всего..."*И-ик!*$B$B"Что? О, ты уже ее починил! Ух, какой ты бысшшштрый. Так шшшо, согласишшшься почшшшинить ешшше одну?"$b$bВы уверены, что слышите, как жидкость льется в емкость, а затем – звучные глотки.', 70888),
(2118, 'ruRU', 'Наша работа только начинается, $n. Вы готовы к следующему заданию?', 70888),
(2438, 'ruRU', 'Мой изумрудный ловец снов очень много для меня значит. Такие подарки лишь немногим дарят. Прими мою благодарность за его возвращение, $n.', 70888),
(2459, 'ruRU', 'Теперь я восстановлю своего ловца снов! Спасибо тебе, $n.', 70888),
(2518, 'ruRU', 'Лес оплакивает леди Сатру, но это надо было сделать.$B$BБлагодарю тебя, $n.', 70888),
(2520, 'ruRU', 'Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновленным духом.$B$BДа примет Элуна ту жертву, что ты $Gпринес:принесла; ей.', 70888),
(2541, 'ruRU', 'Прими мою благодарность, $n.$B$BКакая странная вещица... Я чувствую злую ауру, которую она излучает. Очень мощное заклятие...', 70888),
(2561, 'ruRU', 'Наконец-то я свободен от власти племени Кривой Сосны! Спасибо тебе, $n.$B$BОтныне мой дух обретет вечный покой в объятиях Изумрудного Сна.$B$BВозможно, однажды мы снова встретимся, $Gюный:юная:c; |3-6($c). Но пока прими эту награду в знак моей благодарности.', 70888),
(3521, 'ruRU', 'Хвала Элуне – ты так быстро $Gсобрал:собрала; все ингредиенты!$B$BПодожди минутку, сейчас я приготовлю противоядие.', 70888),
(3522, 'ruRU', 'Что это, $n?$B$BЯ знал, что Дирания поможет мне!$B$B*Иверрон выпивает противоядие.*$B$BЯ все время попадаю в переделки, а Дирания постоянно меня из них вытаскивает.$B$BМне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя. Что ж, надеюсь, ты $Gрасчистил:расчистила; мне дорогу через этот лес, полный мерзостных чащобных тенетников...', 70888),
(3524, 'ruRU', 'Я надеюсь, что мурлоки не слишком досаждали вам, пока вы собирали для нас эти кости! Я непременно следующим же гиппогрифом доставлю их в Дарнасс. Храм Луны снабдил меня некоторыми средствами, которыми я могла бы расплачиваться за помощь; пожалуйста, примите немного денег вместе с нашей благодарностью.$B$BВаш успех побуждает меня предложить вам возможность и дальше оказывать помощь храму Луны, если вы заинтересованы в этом...', 70888),
(4161, 'ruRU', 'Всегда помни то, что я ныне показал тебе, $n. Ты – часть того равновесия, которое ночные эльфы стремятся поддерживать даже в тревожные времена.', 70888),
(4681, 'ruRU', 'Вы чрезвычайно помогли мне сегодня; теперь у нас есть серьезные шансы узнать, почему эти твари выбрасываются на отмели Темного Берега. Мысль о том, что они бегут сюда из прибрежных вод Тельдрассила, очень беспокоит меня. Если вы наткнетесь на другие останки в ваших странствиях, пожалуйста, дайте мне знать. Наши исследования здесь пока на начальной стадии.$B$BОт имени Храма Луны примите, пожалуйста, это в качестве благодарности за ваши труды. Благодарю вас, $n!', 70888),
(4722, 'ruRU', 'Еще одна находка, которую нам надо изучить. Хорошая работа, $n! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете.', 70888),
(4723, 'ruRU', 'Еще одна находка, которую нам надо изучить. Хорошая работа, $n! Эти останки будут исследованы должным образом, когда их доставят в Дарнасс. Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете.', 70888),
(4727, 'ruRU', 'Интересно, что мурлоков там не было. Мы будем иметь это в виду, когда начнем изучать эти останки! Благодарю вас за ваши труды, $n; Храм Луны уполномочил меня передать вам эти деньги в качестве компенсации за потраченное время.', 70888),
(4761, 'ruRU', 'Рад нашей встрече, |3-6($c). Ваше расследование ситуации с фурболгами как нельзя кстати. Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведенной на сами леса. Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена.', 70888),
(4762, 'ruRU', 'Я не удивлен тем, насколько сильно отравлена эта вода, но поглядите, какой мерзостной она становится! Похоже, что нужно действовать как можно скорее, да, $n? К востоку от нас находится Оскверненный лес; это и есть настоящий источник порчи, я в прошлом такой уже видел. Заранее могу сказать, что ваша проба подтвердит это. Наверное, мы могли бы найти средство для исцеления, но нам понадобится помощь, даже чтобы попытаться это сделать. Когда придет время, я надеюсь, $n, вы сможете нам ее предоставить.', 70888),
(4811, 'ruRU', 'Так значит, кристалл существует, $n? Как интересно... В любом случае, вы хорошо справились с заданием; отличная работа!$b$bА какова же природа этого кристалла? Это лишь один вопрос в целом море вопросов... На ум мне приходит и другой: почему лунных совухов тянет к кристаллу? Он безвреден, или же таит в себе зло?$B$BУ меня еще много вопросов, но нам придется пристально изучить кристалл, чтобы добиться хоть каких-то ответов.', 70888),
(4813, 'ruRU', 'Да, похоже, что, хотя мы и знаем теперь о кристалле больше, в результате возникло множество новых вопросов.$B$BЯ пойду с добытой вами информацией в совет Аубердина. Может быть, они подскажут, что делать дальше с этим кристаллом. Если вообще есть о чем говорить – пока что угроза слишком далеко на востоке, чтобы принимаеть ее всерьез.$B$BЧто же касается вас, возьмите это. Считайте это наградой за хорошо проделанную работу, $n.', 70888),
(6063, 'ruRU', 'Отлично, $n! Ты и правда быстро обучаешься.', 70888),
(6071, 'ruRU', 'Да, $Gохотник:охотница; пришла пора.', 70888),
(6101, 'ruRU', 'Вижу в тебе обязательность и понимание всего, чему я научил тебя, $n.', 70888),
(6102, 'ruRU', 'Теперь ты знаешь все, чему я мог тебя обучить, $n. Могу ли дать тебе еще один совет? Хорошенько подумай прежде, чем выбрать первого питомца. Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса? Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе.$B$BЧто же, $n. Ныне я дам тебе умение приручать животное, а так же призывать и отпускать его, когда тебе будет нужно. Гордись своими новыми умениями – ты их честно $Gзаслужил:заслужила;.', 70888),
(6103, 'ruRU', '$GНовоиспеченный охотник:Новоиспеченная охотница;?. Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем. Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке.$B$BЗапомни, $n: всегда уважай равновесие и почитай природу. Теперь ступай. Попозже еще поговорим.', 70888),
(6342, 'ruRU', 'Посылка от Нессы? Спасибо, $n! Она говорила, что собирается прислать мне образцы рыбы, пойманной близ деревни Рут''теран. Она думает, что эта рыба может серьезно отличаться от той, что ловится здесь...$B$BНичего себе! Эта челюсть чуть ли не вдвое больше, чем у таких же здешних рыб. А эта чешуя размером с кулак! Невероятно!', 70888),
(6343, 'ruRU', 'Все это очень интересно. Рыба здесь крупная, но я не думала, что разница между обитающими в материковых и здешних водах столь велика. Для этого должна быть причина...$B$BЧто ж, благодарю вас, $n. Я обсужу с земляками новости, что вы принесли. Может быть, когда-нибудь мы найдем причину этой странности. А пока будем ею пользоваться!', 70888),
(7383, 'ruRU', 'Находиться в присуствии Древа-оракула... это все равно что увидеть воплощенную мудрость. Позволь мне продолжить...$b$bТельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена. Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности. Алекстраза также отказала Оленьему Шлему, а без ее благословения рост Тельдрассила стал непредсказуем, и в нем обнаружились изъяны...', 70888),
(96606, 'ruRU', 'Мы изучили основы, а теперь иди поучись ремеслу у наставников в деревне поблизости. Они даже могут показать, как обустроить лагерь в соответствии с твоей новой профессией.', 70888),
(96630, 'ruRU', 'Это что, мой дневник? Я уже давно его ищу. Спасибо, |3-6($c).$B$BА ты на вид $gтакой же искатель:такая же искательница; приключений, как я. Не хочешь поучиться премудростям походной жизни?', 70888),
(96634, 'ruRU', 'С этим ты сможешь разбить лагерь где угодно. Пока ты $gосвоил:освоила; только азы, так что особенно обставить лагерь не получится.$B$BУчись – и со временем научишься разжигать огонь пожарче и делать разные интересные вещи.$B$BЕще ты можешь научиться создавать разные полезные вещи в лагере – поговори с другими наставниками профессий, в которых хоть немного разбираешься.', 70888),
(97236, 'ruRU', 'Надо же! Обожаю сюрпризы, $n.$B$BВне всяких сомнений, этот экземпляр пригодится для моих исследований.', 70888),
(97942, 'ruRU', 'Вот, теперь ты можешь создать собственный набор первой помощи. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе.$B$BДа, и помни, что без костра никакого лагеря не получится. Так что сначала придется разжечь костер. Этому тебя может научить почти любой специалист по кулинарии. Если еще не $gозаботился:озаботилась; этим, обратись к кому-нибудь из них.', 70888),
(97949, 'ruRU', 'Вот, теперь ты можешь создать собственный лагерный стул. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе.$B$BДа, и помни, что без костра никакого лагеря не получится. Так что сначала придется разжечь костер. Этому тебя может научить почти любой специалист по кулинарии. Если еще не $gозаботился:озаботилась; этим, обратись к кому-нибудь из них.', 70888),
(98025, 'ruRU', 'Хорошо, что проблема решена, хотя мне очень жаль, что нам не удалось найти другой выход. Ждай''ванель давно была своего рода хранительницей этих земель, и я не уверена, что могло подтолкнуть ее к безумию.$B$BВ любом случае, спасибо тебе за услугу, |3-6($c). Теперь дороги к Аубердину снова безопасны.', 70888),
(98046, 'ruRU', 'Не принимай слова верховного друида близко к сердцу, $n. В отсутствие Малфуриона на нем лежит тяжкое бремя.$B$BПодожди! Во флаконе еще осталось несколько капель! Может быть, поэтому его ритуал не удался?', 70888),
(98065, 'ruRU', 'Олений Шлем много трудился в отсутствие моего дорогого Малфуриона, но ему с ним не сравниться. И не он управляет Дарнассом – это бремя лежит только на мне.$B$B<Тиранда расслабляется.>$B$BИзвини. Как ты уже наверняка $gзаметил:заметила;, перед нами стоит множество испытаний.$B$BСейчас Фэндрал – верховный друид, и его авторитет нужно признавать. Но все его дела касаются лишь друидизма, в то время как я не только служу верховной жрицей, но и правлю нашим народом согласно воле Элуны.$B$BКаждая капля этой воды благословлена богиней. Спасибо, что $gсохранил:сохранила; ее.', 70888),
(98067, 'ruRU', 'Спасибо тебе за помощь. Ежедневные ритуалы приносят мне спокойствие, но иногда хочется просто провести несколько минут в размышлениях.', 70888),
(98391, 'ruRU', 'Хорошо, что ты $gпришел:пришла; так быстро. Сестринству нужна твоя помощь.', 70888),
(98392, 'ruRU', '<Арания осматривает амулеты.>$B$BВидишь эти мерзкие зеленые завихрения в самоцветах? Несомненно, это порча от мха Скверны.$B$BГоворят, что в Тенистой долине и других уголках нашего леса также находили это вещество, обращающее наш дом против нас самих.$B$BЯ немедленно доложу об этом командованию.', 70888),
(98398, 'ruRU', 'Когда вы осматриваете опавшую кору, вы слышите голос в своей голове. Спокойная и умиротворяющая речь напоминает вам шелест листвы при легком ветерке.', 70888),
(98403, 'ruRU', 'Нужно было догадаться, что именно этим осквернили местных пауков.$B$BЯ слышал, что эта субстанция является источником порчи, которая принесла нам столько бед. Это не оригинальный образец, но более старый, чем те, что мы находили ранее, так что у нас есть шанс узнать что-то новое.$B$BВ обычной ситуации я бы попросил тебя отправить этот образец в Дарнасс на изучение. Но сейчас лучше, чтобы об этом никто не знал, иначе репутация Доланаара будет навсегда испорчена.$B$BНадеюсь, ты умеешь хранить тайны?', 70888),
(99046, 'ruRU', 'Хвала Элуне... Я не умру... одна...', 70888),
(99047, 'ruRU', 'Гарпий поразила та же порча, что появилась во всех наших лесах. Не удивлюсь, если этим же недугом заражена и часовая Эралия.$B$BНадо поспешить. Еще совсем немного, и она погибнет.', 70888),
(99050, 'ruRU', 'Спасибо за помощь. Вот, возьми это, раз пришлось покупать колбу и воду.$B$BОсталось приготовить бальзам. Это не займет много времени.', 70888),
(99073, 'ruRU', '<Вы помогаете Эралии проглотить бальзам, и ее дыхание становится ровным. Вы не знаете, выживет ли она, но теперь ей хоть немного легче.>', 70888)
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(483, 'ruRU', '$n, похищенные друиды-вороны навеки останутся в ловушке Изумрудного Сна, если мы не сумеем добыть реликвии Пробуждения из обители Бен''этиль, что на западе отсюда.$b$bЧем дольше мы медлим, тем неизбежнее их рок.', 70888),
(487, 'ruRU', 'На дороге все еще неспокойно, |3-6($c). Ступай же и убей 6 душителей из Кривой Сосны, а потом возвращайся ко мне.', 70888),
(488, 'ruRU', 'Ну что, $n, не $gзапыхался:запыхалась;? А я все думал, когда же ты принесешь то, что мне нужно...', 70888),
(489, 'ruRU', 'Ой, $n, ты мне что-то $Gпринес:принесла;? Видать, что-то вкусненькое?', 70888),
(916, 'ruRU', 'Тебе удалось собрать ядовитые железы, $n?', 70888),
(917, 'ruRU', 'Тебе удалось проникнуть в Паучье логово, $n? А найти паучье яйцо?', 70888),
(918, 'ruRU', 'Ты $Gдобыл:добыла; саженцы? Мне не терпится посадить их.', 70888),
(919, 'ruRU', 'Добро пожаловать, $n. $GНашел:Нашла; ли ты ростки у озера?', 70888),
(921, 'ruRU', 'Лунные колодцы содержат воду Источника Вечности, древнего источника магии, который навлек на наш мир так много ужасов.$b$bДруиды пользуются свойствами колодцев, а Стражи чтят их как святилища Элуны, но использовать магию колодцев запрещено всем.', 70888),
(923, 'ruRU', 'Ты $Gбыл:была; у Родникового озера, $n? Удалось поохотиться там на древесников?', 70888),
(928, 'ruRU', 'Привет тебе, |3-6($c). Чем обязан удовольствию встречи с тобой?', 70888),
(929, 'ruRU', 'С возвращением, $n. $GИсполнил:Исполнила; ли ты поручение?', 70888),
(930, 'ruRU', 'Похоже, ты что-то хочешь мне рассказать, $n? Ты что-то знаешь о древесниках?', 70888),
(931, 'ruRU', 'Ты что-то мне $Gпринес:принесла;?', 70888),
(932, 'ruRU', 'Ты еще не $Gубил:убила; лорда Меленаса? Необходимо убрать его быстро и тихо, $n. Его существование – угроза всем нам.', 70888),
(935, 'ruRU', 'Я не звал тебя, так что не понимаю, зачем ты $Gпришел:пришла; отвлекать меня разговорами.$b$bЧто бы там ни было, пожалуйста, побыстрее.', 70888),
(937, 'ruRU', 'Их безжалостные когти и острые клювы могут оказаться для тебя трудным испытанием, $n, но я верю, что ты с честью выдержишь его.', 70888),
(940, 'ruRU', 'Хм-м... В тебе силен дух леса, |3-6($c). Что у тебя за дело к верховному друиду кальдораев?', 70888),
(947, 'ruRU', 'Вы еще не собрали грибов для меня, $n? В пещеру ходили?', 70888),
(956, 'ruRU', 'Столпы этого святилища для меня – тюремная решетка, $n. У меня нет сил их разрушить, и нет такой магии, чтобы сокрушить их...$b$bБольше тысячи лет я смотрю на них и думаю: если я переживу этот камень, буду ли я свободен? Или меня держит незримая решетка?', 70888),
(997, 'ruRU', 'Ты что-то мне $Gпринес:принесла;?', 70888),
(2159, 'ruRU', 'Чем я могу тебе помочь, $Gюноша:девица;? Желаешь отдохнуть на постоялом дворе? Или тебе нужен камень возвращения?', 70888),
(2438, 'ruRU', 'Прошу, быстрее. Могу лишь надеяться, что фурболги не повредили моего ловца снов.$B$BТы еще не $Gдобыл:добыла; его, $n?', 70888),
(3521, 'ruRU', 'Пожалуйста, принеси мне все эти ингредиенты, $n. Иверрону нужна наша помощь!', 70888),
(3522, 'ruRU', 'О... $n, какое счастье, что ты $Gвернулся:вернулась;...', 70888),
(3524, 'ruRU', 'Эти морские твари только недавно стали приплывать на отмели Темных берегов в таких тревожно больших количествах. Не могу сказать точно, но думаю, что это своего рода дурное предзнаменование. Извлечение образцов костей такой твари, что лежит к югу отсюда, поможет нам в Дарнассе оценить ситуацию!', 70888),
(4161, 'ruRU', 'Помни о равновесии, $n. Желаю тебе открыть в себе понимание и любовь к живым лесам.', 70888),
(4722, 'ruRU', 'Здравствуйте, $n, вы хотите рассказать еще что-то о тварях, выбросившихся на берег?', 70888),
(4723, 'ruRU', 'Может, когда-нибудь мы изыщем средство, чтобы несчастные твари больше не заканчивали впустую  свою жизнь на отмелях Темного Берега. А до тех пор мы должны продолжать наши исследования.$B$BПриветствую, $n! С какими вы вестями?', 70888),
(4725, 'ruRU', 'Приятно вновь увидеть вас, $n. Мы прилагаем большие усилия, чтобы узнать, почему же огромные морские существа выбрасываются на пески Темного Берега, но на каждый найденный ответ возникает два новых вопроса.$B$BВы пришли, чтобы снова оказать нам помощь в расследовании?', 70888),
(4727, 'ruRU', 'Приветствую снова, $n! Вы нашли еще каких-то выбросившихся на берег тварей, о которых следовало бы узнать Храму Луны?', 70888),
(6343, 'ruRU', '$n, вы уже вернулись из Аубердина? Вы говорили с Лайрдом?', 70888),
(96630, 'ruRU', 'Ты хочешь поучиться премудростям походной жизни?', 70888),
(98025, 'ruRU', 'Приветствую, |3-6($c). Чем часовые могут помочь тебе? Ты $gпришел:пришла; узнать о награде за голову Джай''ванель?', 70888),
(98046, 'ruRU', 'Чем я могу помочь?', 70888),
(98065, 'ruRU', 'Говори быстрее. У меня, правительницы этого города, много работы.', 70888),
(98392, 'ruRU', 'Ты $gдобыл:добыла; амулеты предводительниц гарпий?', 70888),
(98403, 'ruRU', '<Таллонкай говорит шепотом.>$B$BЗеторр все еще жив?', 70888),
(99050, 'ruRU', 'Ингредиенты у тебя? Боюсь, у Эралии совсем мало времени.', 70888),
(99073, 'ruRU', '<Эралия больше не в силах говорить. Вы понимаете, что она еще жива, по слабому хрипу.>', 70888)
